/**
 * Colour tokens. Source of truth for every colour in the system.
 *
 * Structure (see docs/decisions/0001-colour-palette.md and
 * docs/foundations/colour.md):
 *
 * - `palette`  raw scales, 50 to 950, named by role never by hue. The hex
 *              values are generated by `bun run build:palette` from an OKLCH
 *              recipe in `scripts/build-palette.ts`; edit the recipe, not
 *              the hex, when a hue changes.
 * - `roles`    semantic aliases for surfaces, text, borders and status,
 *              resolved per theme (light, dark).
 * - `registers` which accent scale each audience register uses.
 *
 * Components never reference `palette` directly for surfaces or text; they
 * use the role utilities Tailwind generates (`bg-canvas`, `text-fg-muted`, ...).
 */

import type { Hex } from "../utils/color.ts";

export const colorSteps = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950] as const;
export type ColorStep = (typeof colorSteps)[number];
export type ColorScale = Readonly<Record<ColorStep, Hex>>;

