/**
 * Audience registers (MISSION.md: one brand, two registers). The `accent`
 * scale in Tailwind resolves to one of these depending on the nearest
 * `data-register` ancestor. B2C is the default because it is the public face.
 */
export const registers = ["b2c", "b2b"] as const;
export type Register = (typeof registers)[number];
export const defaultRegister: Register = "b2c";

export const registerAccent: Readonly<Record<Register, PaletteName>> = {
  b2c: "accentB2c",
  b2b: "accentB2b",
};

/** Resolve a reference to its hex value. */
export function resolveColor(color: ColorRef): Hex {
  return "absolute" in color ? absolutes[color.absolute] : palette[color.scale][color.step];
}
